const categories=[['A','A-models'],['AN','AN-models'],['T','T-models'],['TA','TA-models'],['DOOKs',"DOOK’s"]];
let collectionCategory='A',shopCategory='A',shopSearch='';
const shopChoices={},shopBag={};
function catalogueLoading(label){return renderTopbar(label)+`<section class="shop-shell"><p role="${catalogueError?'alert':'status'}">${escapeHTML(catalogueError||'Loading collection…')}</p>${catalogueError?'<button class="pill" data-catalogue-retry>Try again</button>':''}</section>`+footer()}
const tradeModel=id=>window.tradeCatalog.find(p=>p.id===id);
function chosen(p){const choice=shopChoices[p.id]||{colour:0,item:0};const variant=p.variants[choice.colour]||p.variants[0];return {variant,item:variant.items[choice.item]||variant.items[0]}}
function colourPaint(v){const code=v.code.split('/')[0];const known={A1:'#634333',B1:'#232629',B5:'#313332',C1:'#345969',C2:'#344b68',D1:'#987347',F1:'#888b8d',G1:'#4d6143',H1:'#9c886a',R1:'#972e39',T1:'#555d63',T2:'#766454',T3:'#314358',TG:'#b5a16b','GN01-3':'#7b9178',MI01:'#d5b8af','BR01-3':'#8e7355','BR01-GR-2':'linear-gradient(#78654e,#eee7db)','BL01-GR-1':'linear-gradient(#759cae,#e3eff2)','GY01-GR-2':'linear-gradient(#686e71,#eceeed)','GY01-3-PL':'#525958','YE01-NV':'#e3d279','CL01-AB':'#e3eeee','CL01-AB+1,0':'#e3eeee'};return known[code]||'#b5b9b6'}
function categoryTabs(current,mode){return `<div class="category-tabs" role="tablist" aria-label="${mode==='shop'?'Partner shop':'Collection'} categories">${categories.map(([key,label])=>`<button role="tab" aria-selected="${current===key}" class="${current===key?'selected':''}" data-${mode}-category="${key}">${label}<span>${window.tradeCatalog.filter(p=>p.category===key).length}</span></button>`).join('')}</div>`}
function tradePhoto(p,v){const exact=v.images?.[0],image=exact?.src||p.referenceImage;if(!image)return `<div class="model-specimen"><span>${escapeHTML(p.material)}</span><strong>${escapeHTML(p.id)}</strong><small>Product photograph not yet available</small></div>`;return `<div class="shop-photo ${p.pairedImage?'paired-photo':''}"><img src="${escapeHTML(image)}" loading="lazy" alt="${escapeHTML(p.id+' · '+(exact?v.name:p.referenceColour))}">${p.pairedImage?`<img src="${p.pairedImage}" alt="" loading="lazy">`:''}${!exact?`<small>Shown: ${escapeHTML(p.referenceColour)}</small>`:''}</div>`}
function selectedPrice(sku){if(!canPrice()||!priceData||(!priceData.config.enabled&&!isAdmin()))return null;return priceData.prices.find(r=>r.sku===sku)?.amount??null}
function priceLabel(sku){const value=selectedPrice(sku);if(value!==null)return `<strong>${money(value)}</strong><small>${escapeHTML(priceData.config.tax)}${!priceData.config.enabled?' · Draft price':''}</small>`;return `<a href="#login">${canPrice()?'Price on request':'Sign in for prices'}</a>`}
function shopCard(p){const {variant:v,item}=chosen(p);return `<article class="shop-card" data-shop-card="${escapeHTML(p.id)}">${tradePhoto(p,v)}<div class="shop-card-body"><div class="shop-product-heading"><h2>${escapeHTML(p.name||p.id)}</h2><span>${escapeHTML(p.material)}</span></div><div class="shop-swatches" aria-label="${escapeHTML(p.id)} colours">${p.variants.map((v,i)=>`<button type="button" data-shop-colour="${i}" data-model="${p.id}" aria-label="${escapeHTML(p.id+' · '+v.name)}" aria-pressed="${v===chosen(p).variant}" title="${escapeHTML(v.name)}" style="--colour:${colourPaint(v)}"></button>`).join('')}</div><p class="shop-colour-name">${escapeHTML(v.name)}</p><div class="shop-size-price"><label>Lens size<select data-shop-size="${p.id}" aria-label="${p.id} lens size">${v.items.map((x,i)=>`<option value="${i}" ${x===item?'selected':''}>${escapeHTML(x.size)} mm</option>`).join('')}</select></label><div class="shop-price">${priceLabel(item.sku)}</div></div><small class="shop-sku">${escapeHTML(item.sku)}</small>${stockBadge(item.sku)}<div class="shop-add-row"><label>Qty<input data-shop-quantity="${p.id}" type="number" min="1" max="100" value="1" inputmode="numeric" aria-label="${p.id} quantity"></label><button class="pill" data-shop-add="${p.id}" ${!canPrice()?'disabled':''}>Add to selection <span>+</span></button></div></div></article>`}
function shopGrid(){const q=shopSearch.trim().toLowerCase();const visible=window.tradeCatalog.filter(p=>p.category===shopCategory&&(!q||[p.id,p.material,...p.variants.flatMap(v=>[v.name,v.code,...v.items.map(i=>i.sku)])].join(' ').toLowerCase().includes(q)));return visible.length?visible.map(shopCard).join(''):'<p class="shop-empty">No matching models in this category. Try another category or search.</p>'}
function partnerShop(){if(!catalogueReady)return catalogueLoading('THE PARTNER SHOP');const count=Object.values(shopBag).reduce((a,b)=>a+b,0);return renderTopbar('THE PARTNER SHOP')+`<section class="shop-shell"><div class="shop-heading"><div><span class="eyebrow">DOOK FOR PROFESSIONALS</span><h1>Partner shop</h1></div><div class="shop-actions">${isAdmin()?'<a href="#admin" class="text-link">Administration</a>':''}${canPrice()?signOut():'<a class="pill outline" href="#login">B2B login </a>'}<a class="pill" href="#selection">Your selection <span data-bag-count>${count}</span></a></div></div><div class="shop-notice">${account.loading?'Checking your account…':account.error?`<span role="alert">${escapeHTML(account.error)}</span> <button data-retry-account>Try again</button>`:!canPrice()?'Explore the collection. Sign in as an approved partner to see trade prices and select products.':isAdmin()&&!priceData?.config.enabled?'<a href="#admin">Administrator preview · Prices are draft values. Review currency and VAT before activating them for partners. </a>':priceData?.config.enabled?`${escapeHTML(priceData.config.currency)} · ${escapeHTML(priceData.config.tax)} · Select colour, size and quantity.`:'Trade prices are being updated. You can still prepare an enquiry.'}</div>${categoryTabs(shopCategory,'shop')}<label class="shop-search"><span>Search this category</span><input id="shop-search" type="search" value="${escapeHTML(shopSearch)}" placeholder="Model, colour or item number…"></label><div class="shop-grid" id="shop-grid">${shopGrid()}</div></section>`+footer()}
function publicCategoryCard(p){const v=p.variants[0],hasDetail=true;return `<article class="collection-card">${hasDetail?`<button class="collection-photo-button" data-product="${p.id}" aria-label="Explore ${p.id}">${tradePhoto(p,v)}</button>`:tradePhoto(p,v)}<div class="collection-card-info"><h2>${escapeHTML(p.name||p.id)}</h2><p>${escapeHTML(p.material)} · ${p.variants.length} colours</p><div class="collection-colours">${p.variants.map(v=>`<span style="background:${colourPaint(v)}" title="${escapeHTML(v.name)}"></span>`).join('')}</div>${hasDetail?`<button class="text-button" data-product="${p.id}">Explore frame </button>`:`<button class="text-button" data-model-enquiry="${p.id}">Ask about ${p.id} </button>`}</div></article>`}
function categorizedCollection(){if(!catalogueReady)return catalogueLoading('THE COLLECTION');const items=window.tradeCatalog.filter(p=>p.category===collectionCategory);const desc={A:'Acetate frames with a magnetic DOOK system.',AN:'Acetate frames in the AN collection.',T:'Pure titanium frames.',TA:'Titanium frames with an acetate inner rim.',DOOKs:'Magnetic click-ons. Always match the model and lens size to your frame.'};return renderTopbar('THE COLLECTION')+`<section class="page-head"><span class="eyebrow">YOUR FRAME. YOUR PERSPECTIVE.</span><h1>Find your perspective.</h1></section><section class="section collection-section">${categoryTabs(collectionCategory,'collection')}<div class="collection-category-intro"><h2>${categories.find(c=>c[0]===collectionCategory)?.[1]||'Collection'}</h2><p>${escapeHTML(window.liveCategories?.find(c=>c.id===collectionCategory)?.description||desc[collectionCategory]||'')}</p></div><div class="collection-grid">${items.map(publicCategoryCard).join('')}</div></section>`+footer()}
function selectionPage(){if(!catalogueReady)return catalogueLoading('YOUR SELECTION');const lines=Object.entries(shopBag).map(([sku,qty])=>{const p=window.tradeCatalog.find(p=>p.variants.some(v=>v.items.some(x=>x.sku===sku)));const v=p.variants.find(v=>v.items.some(i=>i.sku===sku));return {p,v,item:v.items.find(i=>i.sku===sku),qty}});const allPriced=lines.length&&lines.every(x=>selectedPrice(x.item.sku)!==null);return renderTopbar('YOUR SELECTION')+`<section class="shop-shell"><div class="shop-heading"><h1>Your selection</h1><a href="#partners" class="text-link">Continue shopping </a></div>${!lines.length?'<p class="shop-empty">Your selection is empty. Choose a model, colour and size in the partner shop.</p>':`<div class="selection-list">${lines.map(({p,v,item,qty})=>`<div class="selection-row"><div><strong>${p.id}</strong><p>${escapeHTML(v.name)} · ${escapeHTML(item.size)} mm</p><small>${escapeHTML(item.sku)}</small></div><label>Qty<input type="number" min="1" max="100" data-bag-quantity="${escapeHTML(item.sku)}" value="${qty}"></label><div class="selection-price">${selectedPrice(item.sku)!==null?money(selectedPrice(item.sku)*qty):'Price on request'}</div><button class="text-button" data-bag-remove="${escapeHTML(item.sku)}" aria-label="Remove ${escapeHTML(item.sku)}">Remove</button></div>`).join('')}</div>${allPriced?`<div class="selection-total"><span>Total · ${escapeHTML(priceData.config.tax)}${!priceData.config.enabled?' · Draft':''}</span><strong>${money(lines.reduce((s,l)=>s+selectedPrice(l.item.sku)*l.qty,0))}</strong></div>`:''}<p class="note">DOOK will confirm prices and availability. Your selection stays here while this page is open.</p>${canPrice()&&priceData?.config.enabled&&allPriced?`<form id="submit-trade-order" class="order-request-form"><h2>Send your order request</h2><label>Company<input name="company" maxlength="200" required autocomplete="organization"></label><label>Delivery address<textarea name="delivery" rows="3" maxlength="1500" required autocomplete="street-address"></textarea></label><label>Order notes (optional)<textarea name="note" maxlength="2000" rows="2"></textarea></label><p>Your request is saved for DOOK to review. It is not yet a confirmed order.</p><button class="pill">Submit order request</button><p class="form-status" role="status"></p></form>`:""}<button class="pill" id="compose-shop-enquiry" ${!canPrice()?'disabled':''}>Alternatively, compose an email </button><p id="selection-status" role="status"></p>`}</section>`+footer()}
function repaintShopCard(id){const card=document.querySelector(`[data-shop-card="${id}"]`);if(card)card.outerHTML=shopCard(tradeModel(id));}
document.addEventListener('click',e=>{
 const cat=e.target.closest('[data-shop-category]');if(cat){shopCategory=cat.dataset.shopCategory;render();document.querySelector(`[data-shop-category="${shopCategory}"]`).focus()}
 const collection=e.target.closest('[data-collection-category]');if(collection){collectionCategory=collection.dataset.collectionCategory;render();document.querySelector(`[data-collection-category="${collectionCategory}"]`).focus()}
 const colour=e.target.closest('[data-shop-colour]');if(colour){shopChoices[colour.dataset.model]={colour:Number(colour.dataset.shopColour),item:0};repaintShopCard(colour.dataset.model);document.querySelector(`[data-model="${colour.dataset.model}"][data-shop-colour="${colour.dataset.shopColour}"]`).focus()}
 const add=e.target.closest('[data-shop-add]');if(add&&canPrice()){const id=add.dataset.shopAdd,input=document.querySelector(`[data-shop-quantity="${id}"]`);if(!input.reportValidity())return;const qty=Number(input.value);if(!Number.isInteger(qty)||qty<1||qty>100)return;const sku=chosen(tradeModel(id)).item.sku;shopBag[sku]=Math.min(100,(shopBag[sku]||0)+qty);document.querySelectorAll('[data-bag-count]').forEach(x=>x.textContent=Object.values(shopBag).reduce((a,b)=>a+b,0));const toast=document.querySelector('.toast');toast.textContent=`${qty} × ${id} added to your selection`;toast.hidden=false;setTimeout(()=>toast.hidden=true,2400)}
 const remove=e.target.closest('[data-bag-remove]');if(remove){delete shopBag[remove.dataset.bagRemove];render()}
 const enquiry=e.target.closest('[data-model-enquiry]');if(enquiry){contactDraft=`Hello DOOK,\n\nI would like to know more about ${enquiry.dataset.model}, its colours and available sizes.\n\n`;location.hash='contact'}
 if(e.target.closest('#compose-shop-enquiry')&&canPrice()){const body='Hello DOOK,\n\nPlease confirm the following order enquiry:\n\n'+Object.entries(shopBag).map(([sku,q])=>`${q} × ${sku}`).join('\n')+'\n\nCompany:\nCustomer number:\nDelivery address:\n\nPlease confirm prices and availability.';const uri='mailto:info@dook.dk?subject='+encodeURIComponent('DOOK order enquiry')+'&body='+encodeURIComponent(body);if(uri.length>7000){document.querySelector('#selection-status').textContent='This selection is too large for an email link. Please split it into smaller enquiries.';return}location.href=uri}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-shop-size]')){const id=e.target.dataset.shopSize;shopChoices[id]={colour:shopChoices[id]?.colour||0,item:Number(e.target.value)};repaintShopCard(id);document.querySelector(`[data-shop-size="${id}"]`).focus()}if(e.target.matches('[data-bag-quantity]')){if(!e.target.reportValidity())return;const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=100){shopBag[e.target.dataset.bagQuantity]=n;render()}}});
document.addEventListener('input',e=>{if(e.target.id==='shop-search'){shopSearch=e.target.value;document.querySelector('#shop-grid').innerHTML=shopGrid()}});
